"use client";

import { useEffect, useState } from "react";

import { getObservations } from "@/lib/api/observations";
import { ObservationGrid } from "@/components/observation-grid";

/* ================= TYPES MATCH BACKEND ================= */

interface Observation {
  id: string;
  identityId: string;
  cameraId: string;
  timestamp: string;
  imagePath: string;
}

/* ======================================================= */

export default function ObservationsPage() {
  const [observations, setObservations] = useState<Observation[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  /* ================= FETCH ================= */

  useEffect(() => {
    const fetchObservations = async () => {
      setIsLoading(true);

      try {
        const data = await getObservations();
        setObservations(data);
      } catch (error) {
        console.error("Error fetching observations:", error);
      } finally {
        setIsLoading(false);
      }
    };

    fetchObservations();
  }, []);

  /* ================= STATS ================= */

  const getCameraCount = () => {
    return new Set(observations.map((obs) => obs.cameraId)).size;
  };

  const getIdentityCount = () => {
    return new Set(observations.map((obs) => obs.identityId)).size;
  };

  /* ================= UI ================= */

  return (
    <div className="space-y-6 p-6">
      {/* ================= HEADER ================= */}

      <div>
        <h1 className="text-3xl font-bold text-white mb-2">Observations</h1>

        <p className="text-gray-400">
          Live detections captured from all surveillance cameras
        </p>
      </div>

      {/* ================= METRICS ================= */}

      <div className="grid grid-cols-3 gap-4">
        <div className="bg-[#222] border border-[#333] rounded-lg p-4">
          <p className="text-sm text-gray-400">Total Observations</p>

          <p className="text-2xl font-bold text-white mt-1">
            {observations.length}
          </p>
        </div>

        <div className="bg-[#222] border border-[#333] rounded-lg p-4">
          <p className="text-sm text-gray-400">Active Cameras</p>

          <p className="text-2xl font-bold text-cyan-400 mt-1">
            {getCameraCount()}
          </p>
        </div>

        <div className="bg-[#222] border border-[#333] rounded-lg p-4">
          <p className="text-sm text-gray-400">Unique Identities</p>

          <p className="text-2xl font-bold text-green-400 mt-1">
            {getIdentityCount()}
          </p>
        </div>
      </div>

      {/* ================= GRID ================= */}

      <div>
        <h2 className="text-xl font-bold text-white mb-4">Detection Feed</h2>

        <ObservationGrid observations={observations} isLoading={isLoading} />
      </div>
    </div>
  );
}
