const API_BASE_URL =
  process.env.NEXT_PUBLIC_API_BASE_URL || "http://localhost:5000";

export interface Observation {
  id: string;
  identityId: string;
  cameraId: string;
  timestamp: string;
  imagePath: string;
}

interface ApiResponse<T> {
  success: boolean;
  data: T;
  count?: number;
}

export async function getObservations(): Promise<Observation[]> {
  try {
    const response = await fetch(`${API_BASE_URL}/api/observations`, {
      cache: "no-store",
      credentials: "include",
    });

    const data: ApiResponse<Observation[]> = await response.json();
    return data.success ? data.data : [];
  } catch (error) {
    console.error("Failed to fetch observations:", error);
    return [];
  }
}

export async function getObservationsByCamera(
  cameraId: string,
): Promise<Observation[]> {
  try {
    const response = await fetch(
      `${API_BASE_URL}/api/observations/camera/${cameraId}`,
      {
        cache: "no-store",
        credentials: "include",
      },
    );

    const data: ApiResponse<Observation[]> = await response.json();
    return data.success ? data.data : [];
  } catch (error) {
    console.error(
      `Failed to fetch observations for camera ${cameraId}:`,
      error,
    );
    return [];
  }
}
